# area: inheritance_mro
# hypothesis: super() in a diamond hierarchy follows the C3 MRO at runtime, so Diamond calls Left, then Right, then Base, while a checker must accept that call chain and reject the parameter-narrowing override in Narrow as an LSP violation.
from typing import reveal_type


class Base:
    def greet(self, n: int) -> str:
        return 'base'


class Left(Base):
    def greet(self, n: int) -> str:
        return 'left+' + super().greet(n)


class Right(Base):
    def greet(self, n: int) -> str:
        return 'right+' + super().greet(n)


class Diamond(Left, Right):
    def greet(self, n: int) -> str:
        return 'diamond+' + super().greet(n)


class Narrow(Base):
    def greet(self, n: str) -> str:  # expect-error: parameter type narrowed, violates LSP
        return 'narrow:' + n


print(Diamond().greet(1))
print([k.__name__ for k in Diamond.__mro__])
reveal_type(Diamond().greet(1))
print(Narrow().greet('x'))
